import copy
import decimal
import json
import random
import tomllib
from decimal import Decimal
from pathlib import Path

with open(Path(__file__).parent / "data.toml", "rb") as _f:
    DATA = tomllib.load(_f)


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _int(v, minimum):
    return isinstance(v, int) and not isinstance(v, bool) and v >= minimum


def _op(fn):
    def wrapper(self, *a, **k):
        snap = self._snap()
        prev = self._undo
        try:
            r = fn(self, *a, **k)
        except BaseException:
            self._restore(snap)
            self._undo = prev
            raise
        self._undo = snap
        self._blocked = False
        return r
    wrapper.__name__ = fn.__name__
    return wrapper


_STATE = ("items", "lots", "_cash", "_day", "notes", "rel", "orders", "susp",
          "next_id", "shipped", "returned", "shiplog", "held_close",
          "disarmed", "overdrawn")


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
                 late_penalty_pct=None, perishable_return_policy=None):
        if len(set(warehouses)) != len(warehouses):
            raise DepotError("INVALID_ARGUMENT")
        for w in warehouses:
            if w not in capacities:
                raise DepotError("INVALID_ARGUMENT")
        if not isinstance(opening_cash, int) or isinstance(opening_cash, bool):
            raise DepotError("INVALID_ARGUMENT")
        self.warehouses = list(warehouses)
        self.capacities = {w: capacities[w] for w in warehouses}
        self.rounding_mode = rounding_mode
        self.late_penalty_pct = late_penalty_pct  # undecided; unused
        self.perishable_return_policy = perishable_return_policy
        self.items = {}
        self.lots = {}
        self._cash = opening_cash
        self._day = 0
        self.notes = []
        self.rel = {}
        self.orders = {}
        self.susp = set()
        self.next_id = 1
        self.shipped = {}
        self.returned = {}
        self.shiplog = []
        self.held_close = {}
        self.disarmed = set()
        self.overdrawn = opening_cash < 0
        self._undo = None
        self._blocked = False

    # ---- state helpers
    def _snap(self):
        return copy.deepcopy({k: getattr(self, k) for k in _STATE})

    def _restore(self, snap):
        for k, v in copy.deepcopy(snap).items():
            setattr(self, k, v)

    @property
    def cash(self):
        return self._cash

    @property
    def day(self):
        return self._day

    def _emit(self, *n):
        self.notes.append(tuple(n))

    def _sku(self, sku):
        if sku not in self.items:
            raise DepotError("UNKNOWN_SKU")

    def _wh(self, wh):
        if wh not in self.capacities:
            raise DepotError("UNKNOWN_WAREHOUSE")

    def _qty(self, qty):
        if not _int(qty, 1):
            raise DepotError("INVALID_QTY")

    def _stock(self, sku, wh):
        return sum(q for _, q in self.lots.get((sku, wh), []))

    def _units(self, wh=None):
        return sum(q for (s, w), ls in self.lots.items()
                   if wh is None or w == wh for _, q in ls)

    def _rearm(self, sku, wh):
        if self._stock(sku, wh) > self.items[sku]["reorder_level"]:
            self.disarmed.discard((sku, wh))

    def _round(self, d):
        return int(d.quantize(Decimal(1), rounding=self.rounding_mode))

    # ---- inventory
    @_op
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        if sku in self.items:
            raise DepotError("DUPLICATE_SKU")
        if not _int(unit_cost, 1) or not _int(reorder_level, 0):
            raise DepotError("INVALID_ARGUMENT")
        if shelf_life_days is not None:
            if not _int(shelf_life_days, 0):
                raise DepotError("INVALID_ARGUMENT")
            if shelf_life_days == 0:
                shelf_life_days = None
        self.items[sku] = {"unit_cost": unit_cost,
                           "reorder_level": reorder_level,
                           "shelf_life_days": shelf_life_days}

    def _receive(self, sku, qty, wh):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if self._cash < 0:
            raise DepotError("OVERDRAWN")
        if self._units(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        cost = self.items[sku]["unit_cost"] * qty
        if self._cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._cash -= cost
        self.lots.setdefault((sku, wh), []).append([self._day, qty])
        self._rearm(sku, wh)

    @_op
    def receive(self, sku, qty, wh):
        self._receive(sku, qty, wh)

    @_op
    def receive_bulk(self, receipts):
        for sku, qty, wh in receipts:
            self._receive(sku, qty, wh)

    def list_price(self, sku):
        self._sku(sku)
        d = Decimal(self.items[sku]["unit_cost"]) * (1 + Decimal(str(DATA["markup"])))
        return self._round(d)

    @_op
    def ship(self, sku, qty, wh, price):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if not _int(price, 0):
            raise DepotError("INVALID_PRICE")
        if self._stock(sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        need = qty
        lots = self.lots[(sku, wh)]
        while need:
            if lots[0][1] <= need:
                need -= lots[0][1]
                lots.pop(0)
            else:
                lots[0][1] -= need
                need = 0
        total = Decimal(price) * qty
        if qty >= DATA["bulk_threshold"]:
            total = total * (100 - Decimal(str(DATA["bulk_discount_pct"]))) / 100
        revenue = self._round(total)
        self._cash += revenue
        self.shipped[sku] = self.shipped.get(sku, 0) + qty
        self.shiplog.append([self._day, qty])
        level = self.items[sku]["reorder_level"]
        if self._stock(sku, wh) <= level and (sku, wh) not in self.disarmed:
            self.disarmed.add((sku, wh))
            self._emit("REORDER", sku, wh)
        return revenue

    @_op
    def transfer(self, sku, qty, from_wh, to_wh):
        self._sku(sku)
        self._wh(from_wh)
        self._wh(to_wh)
        self._qty(qty)
        if from_wh == to_wh:
            raise DepotError("SAME_WAREHOUSE")
        if self._stock(sku, from_wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        if self._units(to_wh) + qty > self.capacities[to_wh]:
            raise DepotError("CAPACITY")
        cost = DATA["transfer_credit_cents_per_unit"] * qty
        if self._cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._cash -= cost
        need = qty
        src = self.lots[(sku, from_wh)]
        dst = self.lots.setdefault((sku, to_wh), [])
        while need:
            take = min(need, src[0][1])
            dst.append([src[0][0], take])
            src[0][1] -= take
            need -= take
            if src[0][1] == 0:
                src.pop(0)
        dst.sort(key=lambda l: l[0])  # stable: keeps FIFO by stamp
        self._rearm(sku, to_wh)

    @_op
    def return_goods(self, sku, qty, wh, price):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if not _int(price, 0):
            raise DepotError("INVALID_PRICE")
        if self.returned.get(sku, 0) + qty > self.shipped.get(sku, 0):
            raise DepotError("RETURN_EXCEEDS")
        perishable = self.items[sku]["shelf_life_days"] is not None
        restock = True
        if perishable:
            pol = self.perishable_return_policy
            if pol not in ("restock", "discard"):
                raise DepotError("UNDECIDED_POLICY")
            restock = pol == "restock"
        if restock:
            if self._units(wh) + qty > self.capacities[wh]:
                raise DepotError("CAPACITY")
            self.lots.setdefault((sku, wh), []).append([self._day, qty])
            self._rearm(sku, wh)
        self.returned[sku] = self.returned.get(sku, 0) + qty
        self._cash += price * qty

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._wh(wh)
            return self._stock(sku, wh)
        return sum(self._stock(sku, w) for w in self.warehouses)

    def report(self):
        rows = []
        for sku in sorted(self.items):
            for wh in sorted(self.warehouses):
                u = self._stock(sku, wh)
                rows.append((sku, wh, u, u * self.items[sku]["unit_cost"]))
        return rows

    @_op
    def audit(self, counts):
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for sku, wh in counts:
            self._sku(sku)
            self._wh(wh)
        for (sku, wh) in sorted(counts):
            led = self._stock(sku, wh)
            if led != counts[(sku, wh)]:
                self._emit("AUDIT_MISMATCH", sku, wh, led, counts[(sku, wh)])

    # ---- time
    def advance_day(self):
        snap = self._snap()
        try:
            self._advance()
        except BaseException:
            self._restore(snap)
            raise
        self._undo = None
        self._blocked = True

    def _advance(self):
        self.held_close[self._day] = self._units()
        self._cash -= DATA["storage_cents_per_unit_day"] * self._units()
        self._day += 1
        for (sku, wh) in sorted(self.lots):
            shelf = self.items[sku]["shelf_life_days"]
            if shelf is None:
                continue
            lots = self.lots[(sku, wh)]
            gone = sum(q for d, q in lots if self._day - d > shelf)
            if gone:
                self.lots[(sku, wh)] = [l for l in lots if self._day - l[0] <= shelf]
                self._emit("EXPIRY", sku, wh, gone)
        if self._cash < 0 and not self.overdrawn:
            self._emit("OVERDRAWN")
        self.overdrawn = self._cash < 0

    def notifications(self):
        return list(self.notes)

    def undo(self):
        if self._blocked:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        self._restore(self._undo)
        self._undo = None

    def turnover(self, start_day, end_day):
        if not _int(start_day, 0) or not _int(end_day, start_day if _int(start_day, 0) else 0):
            raise DepotError("INVALID_RANGE")
        units = sum(q for d, q in self.shiplog if start_day <= d <= end_day)
        held = []
        for d in range(start_day, end_day + 1):
            if d == self._day:
                held.append(self._units())
            elif d in self.held_close:
                held.append(self.held_close[d])
        if not held:
            return None
        avg = Decimal(sum(held)) / len(held)
        if avg == 0:
            return None
        return float(Decimal(units) / avg)

    # ---- suppliers
    @_op
    def place_order(self, supplier, sku, qty, due_day):
        self._sku(sku)
        self._qty(qty)
        if not isinstance(due_day, int) or isinstance(due_day, bool):
            raise DepotError("INVALID_ARGUMENT")
        if supplier in self.susp:
            raise DepotError("SUPPLIER_SUSPENDED")
        self.rel.setdefault(supplier, 3)
        oid = self.next_id
        self.next_id += 1
        self.orders[oid] = {"supplier": supplier, "sku": sku, "qty": qty,
                            "due_day": due_day, "delivered": False}
        return oid

    @_op
    def deliver(self, order_id, day):
        o = self.orders.get(order_id)
        if o is None:
            raise DepotError("UNKNOWN_ORDER")
        if o["delivered"]:
            raise DepotError("ALREADY_DELIVERED")
        o["delivered"] = True
        s = o["supplier"]
        r = self.rel[s] + (-1 if day > o["due_day"] else 1)
        self.rel[s] = max(0, min(5, r))
        if self.rel[s] <= 1 and s not in self.susp:
            self.susp.add(s)
            self._emit("SUPPLIER_SUSPENDED", s)

    @_op
    def reinstate(self, supplier):
        if supplier not in self.rel:
            raise DepotError("UNKNOWN_SUPPLIER")
        self.rel[supplier] = 2
        self.susp.discard(supplier)

    def reliability(self, supplier):
        if supplier not in self.rel:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self.rel[supplier]

    # ---- persistence
    def save(self):
        d = {
            "version": 1,
            "items": self.items,
            "lots": [[s, w, l] for (s, w), l in self.lots.items()],
            "cash": self._cash,
            "day": self._day,
            "notes": [list(n) for n in self.notes],
            "rel": self.rel,
            "orders": {str(k): v for k, v in self.orders.items()},
            "susp": sorted(self.susp),
            "next_id": self.next_id,
            "shipped": self.shipped,
            "returned": self.returned,
            "shiplog": self.shiplog,
            "held_close": {str(k): v for k, v in self.held_close.items()},
            "disarmed": sorted([list(x) for x in self.disarmed]),
            "overdrawn": self.overdrawn,
        }
        return json.dumps(d)

    @_op
    def load(self, s):
        try:
            d = json.loads(s)
            if not isinstance(d, dict) or d.get("version") != 1:
                raise ValueError
            items = d["items"]
            lots = {(a, b): [[int(x), int(y)] for x, y in l]
                    for a, b, l in d["lots"]}
            for (a, b) in lots:
                if a not in items or b not in self.capacities:
                    raise ValueError
            cash = d["cash"]
            day = d["day"]
            if not isinstance(cash, int) or not isinstance(day, int):
                raise ValueError
            new = {
                "items": items, "lots": lots, "_cash": cash, "_day": day,
                "notes": [tuple(n) for n in d["notes"]],
                "rel": dict(d["rel"]),
                "orders": {int(k): v for k, v in d["orders"].items()},
                "susp": set(d["susp"]),
                "next_id": int(d["next_id"]),
                "shipped": dict(d["shipped"]),
                "returned": dict(d["returned"]),
                "shiplog": [[int(a), int(b)] for a, b in d["shiplog"]],
                "held_close": {int(k): int(v) for k, v in d["held_close"].items()},
                "disarmed": {tuple(x) for x in d["disarmed"]},
                "overdrawn": bool(d["overdrawn"]),
            }
            for it in items.values():
                it["unit_cost"], it["reorder_level"], it["shelf_life_days"]
        except Exception:
            raise DepotError("BAD_SAVE")
        for k, v in new.items():
            setattr(self, k, v)


def simulate(days, seed):
    rng = random.Random(seed)
    out = []
    for _ in range(days):
        day = []
        for sku, rng_ in DATA["demand"].items():
            q = rng.randint(rng_["min"], rng_["max"])
            if q > 0:
                day.append((sku, q))
        out.append(day)
    return out
